      function forgerEquipementIdleV25_(
        slot
      ){
        if(
          !SOREAL_SESSION ||
          !idleEtat ||
          !idleEtat.equipement
        ){
          return;
        }

        const objet=
          idleEtat.equipement[
            slot
          ];

        if(!objet){
          messageFlottantIdleV32_(
            '❌ Aucun objet équipé.'
          );
          return;
        }

        const forgeEtat=
          idleEtat.forge &&
          idleEtat.forge[slot]
            ?idleEtat.forge[slot]
            :null;

        const cout=
          Math.max(
            1,
            idleEntier_(
              forgeEtat&&forgeEtat.cout
            )
          );

        if(
          idleEntier_(
            idleEtat.materiaux
          )<cout
        ){
          messageFlottantIdleV32_(
            '❌ Pas assez de matériaux.'
          );
          return;
        }

        idleEtat.materiaux=
          Math.max(
            0,
            idleEntier_(
              idleEtat.materiaux
            )-
            cout
          );

        const avant=
          idleNombre_(
            objet.bonusPuissance
          );

        objet.forge=
          idleEntier_(
            objet.forge
          )+1;

        objet.bonusPuissance=
          Math.max(
            1,
            Math.round(
              avant*1.18+1
            )
          );

        if(
          Array.isArray(
            idleEtat.inventaire
          )
        ){
          const indexInventaire=
            idleEtat.inventaire.findIndex(
              function(item){
                return String(
                  item&&item.id||''
                )===
                String(
                  objet.id||''
                );
              }
            );

          if(indexInventaire>=0){
            idleEtat.inventaire[
              indexInventaire
            ]=
              objet;
          }
        }

        const delta=
          idleNombre_(
            objet.bonusPuissance
          )-
          avant;

        idleEtat.puissance=
          Math.max(
            1,
            idleNombre_(
              idleEtat.puissance
            )+
            delta
          );

        idleEtat.bonusEquipement=
          Math.max(
            0,
            idleNombre_(
              idleEtat.bonusEquipement
            )+
            delta
          );

        if(!idleEtat.forge){
          idleEtat.forge={};
        }

        const meta=
          idleEtat.forgeMeta||{
            base:5,
            croissance:1.65
          };

        idleEtat.forge[slot]={
          niveau:
            idleEntier_(
              objet.forge
            ),
          cout:
            Math.max(
              1,
              Math.round(
                idleNombre_(
                  meta.base
                )*
                Math.pow(
                  Math.max(
                    1,
                    idleNombre_(
                      meta.croissance
                    )
                  ),
                  idleEntier_(
                    objet.forge
                  )
                )
              )
            )
        };

        planifierRenduOptimisteIdleV60_();

        ajouterActionRapideIdleV60_(
          'forge',
          slot
        );

        messageFlottantIdleV32_(
          '🔥 Forge +'+
          idleEntier_(
            objet.forge
          )
        );
      }


      window.__forgerEquipementIdleV25__=forgerEquipementIdleV25_;


