      function equiperObjetIdleV10_(
        objetId
      ){
        libererFocusIdleV24_();
        if(equipementBloqueParDefiIdleV1_()){
          refuserEquipementDefiIdleV1_();
          return;
        }

        if(
          !idleEtat ||
          !objetId ||
          !SOREAL_SESSION
        ){
          return;
        }

        jouerEffetAudioIdleV199_('equip');

        const inventaire=
          Array.isArray(
            idleEtat.inventaire
          )
            ?idleEtat.inventaire
            :[];

        const objet=
          inventaire.find(
            function(item){
              return String(
                item&&item.id||''
              )===
              String(
                objetId
              );
            }
          );

        if(!objet){
          return;
        }

        if(!idleEtat.equipement){
          idleEtat.equipement={};
        }

        const slot=
          String(
            objet.slot||''
          );

        const ancien=
          idleEtat.equipement[
            slot
          ]||null;

        /* Historique V8: docs/UI-MONOLITH-HISTORY.md#bloc-95 */
        idleEtat.equipement[
          slot
        ]=
          objet;

        if(!ancien){
          idleEtat.inventaireUtilise=
            Math.max(
              0,
              idleEntier_(
                idleEtat.inventaireUtilise
              )-1
            );

          idleEtat.inventaireLibre=
            Math.max(
              0,
              idleEntier_(
                idleEtat.inventaireCapacite
              )-
              idleEntier_(
                idleEtat.inventaireUtilise
              )
            );
        }

        if(!idleEtat.forge){
          idleEtat.forge={};
        }

        const forgeMeta=
          idleEtat.forgeMeta||{
            base:5,
            croissance:1.65
          };

        const forgeNiveau=
          idleEntier_(
            objet.forge
          );

        idleEtat.forge[slot]={
          niveau:
            forgeNiveau,
          cout:
            Math.max(
              1,
              Math.round(
                idleNombre_(
                  forgeMeta.base
                )*
                Math.pow(
                  Math.max(
                    1,
                    idleNombre_(
                      forgeMeta.croissance
                    )
                  ),
                  forgeNiveau
                )
              )
            )
        };

        const delta=
          idleNombre_(
            objet.bonusPuissance
          )-
          idleNombre_(
            ancien&&ancien.bonusPuissance
          );

        idleEtat.bonusEquipement=
          Math.max(
            0,
            idleNombre_(
              idleEtat.bonusEquipement
            )+
            delta
          );

        idleEtat.puissance=
          Math.max(
            1,
            idleNombre_(
              idleEtat.puissance
            )+
            delta
          );

        planifierRenduOptimisteIdleV60_();

        ajouterActionRapideIdleV60_(
          'equip',
          String(objetId)
        );

        messageFlottantIdleV32_(
          '🛡️ Équipé'
        );
      }


      function acheterAmeliorationIdleV12_(
        type
      ){
        libererFocusIdleV24_();

        if(
          !idleEtat ||
          !SOREAL_SESSION ||
          [
            'production',
            'capacite',
            'puissance'
          ].indexOf(type)===-1
        ){
          return;
        }

        const cout=
          idleEntier_(
            idleEtat &&
            idleEtat.coutsBoutique &&
            idleEtat.coutsBoutique[type]
          );

        if(cout<=0){
          messageFlottantIdleV32_(
            '❌ Coût introuvable.'
          );
          return;
        }

        if(
          idleEntier_(
            idleEtat.pieces
          )<cout
        ){
          messageFlottantIdleV32_(
            '❌ Pas assez d’or.'
          );
          return;
        }

        if(!idleEtat.ameliorations){
          idleEtat.ameliorations={
            production:0,
            capacite:0,
            puissance:0
          };
        }

        idleEtat.pieces=
          Math.max(
            0,
            idleEntier_(
              idleEtat.pieces
            )-
            cout
          );

        idleEtat.ameliorations[type]=
          idleEntier_(
            idleEtat.ameliorations[type]
          )+1;

        const niveau=
          idleEntier_(
            idleEtat.ameliorations[type]
          );

        const meta=
          idleEtat &&
          idleEtat.boutiqueMeta &&
          idleEtat.boutiqueMeta[type]
            ?idleEtat.boutiqueMeta[type]
            :null;

        if(
          meta &&
          idleEtat.coutsBoutique
        ){
          idleEtat.coutsBoutique[type]=
            Math.max(
              1,
              Math.round(
                idleNombre_(
                  meta.base
                )*
                Math.pow(
                  Math.max(
                    1,
                    idleNombre_(
                      meta.croissance
                    )
                  ),
                  niveau
                )
              )
            );

          if(!idleEtat.bonusBoutique){
            idleEtat.bonusBoutique={};
          }

          const ancienBonusV111=
            idleNombre_(
              idleEtat.bonusBoutique[type]
            );

          const nouveauBonusV111=
            niveau*
            idleNombre_(
              meta.bonusParNiveau
            );

          idleEtat.bonusBoutique[type]=
            nouveauBonusV111;

          const deltaBonusV111=
            nouveauBonusV111-
            ancienBonusV111;

          if(type==='production'){
            idleEtat.productionSeconde=
              Math.max(
                .01,
                idleNombre_(
                  idleEtat.productionSeconde
                )+
                deltaBonusV111
              );
          }else if(type==='capacite'){
            idleEtat.energieMax=
              Math.max(
                1,
                idleNombre_(
                  idleEtat.energieMax
                )+
                deltaBonusV111
              );
          }else if(type==='puissance'){
            idleEtat.puissance=
              Math.max(
                1,
                idleNombre_(
                  idleEtat.puissance
                )+
                deltaBonusV111
              );
          }
        }

        planifierRenduOptimisteIdleV60_();

        ajouterActionRapideIdleV60_(
          'shop',
          type
        );
      }


