      function fusionnerLootIdleV21_(
        objetId
      ){
        libererFocusIdleV24_();

        if(
          !objetId ||
          !SOREAL_SESSION ||
          !idleEtat
        ){
          return;
        }

        const inventaire=
          Array.isArray(
            idleEtat.inventaire
          )
            ?idleEtat.inventaire
            :[];

        const index=
          inventaire.findIndex(
            function(o){
              return String(
                o&&o.id||''
              )===
              String(
                objetId
              );
            }
          );

        if(index<0){
          return;
        }

        const objet=
          inventaire[index];

        const fusionActuelle=
          idleEntier_(
            objet.fusion
          );

        const doublon=
          inventaire.findIndex(
            function(o,i){
              return (
                i!==index &&
                String(o&&o.nom||'')===
                  String(objet.nom||'') &&
                String(o&&o.slot||'')===
                  String(objet.slot||'') &&
                String(o&&o.rarete||'')===
                  String(objet.rarete||'') &&
                idleEntier_(
                  o&&o.fusion
                )===
                  fusionActuelle &&
                !objetEquipeIdleV10_(
                  idleEtat,
                  o
                )
              );
            }
          );

        if(doublon<0){
          messageFlottantIdleV32_(
            '❌ Il faut un deuxième exemplaire identique.'
          );
          return;
        }

        const avant=
          idleNombre_(
            objet.bonusPuissance
          );

        objet.fusion=
          fusionActuelle+1;

        objet.bonusPuissance=
          Math.max(
            1,
            Math.round(
              avant*1.15
            )
          );

        inventaire.splice(
          doublon,
          1
        );

        idleEtat.inventaire=
          inventaire;

        idleEtat.inventaireUtilise=
          Math.max(
            0,
            inventaire.filter(
              function(o){
                return !objetEquipeIdleV10_(
                  idleEtat,
                  o
                );
              }
            ).length
          );

        if(
          objetEquipeIdleV10_(
            idleEtat,
            objet
          )
        ){
          if(
            idleEtat.equipement &&
            objet.slot
          ){
            idleEtat.equipement[
              objet.slot
            ]=
              objet;
          }

          const delta=
            idleNombre_(
              objet.bonusPuissance
            )-
            avant;

          idleEtat.puissance=
            Math.max(
              1,
              idleNombre_(
                idleEtat.puissance
              )+
              delta
            );

          idleEtat.bonusEquipement=
            Math.max(
              0,
              idleNombre_(
                idleEtat.bonusEquipement
              )+
              delta
            );
        }

        planifierRenduOptimisteIdleV60_();

        ajouterActionRapideIdleV60_(
          'fusion',
          String(objetId)
        );

        messageFlottantIdleV32_(
          '🔗 Fusion +'+
          idleEntier_(
            objet.fusion
          )
        );
      }


