      function cooldownAventureRestantIdleV100_(){
        const fin=
          idleEtat&&
          idleEtat.aventure
            ?Math.max(
                0,
                idleNombre_(
                  idleEtat.aventure.cooldownJusqua
                )
              )
            :0;

        return Math.max(
          0,
          (
            fin-
            heureServeurIdleV1_()
          )/
          1000
        );
      }


      function actualiserCooldownAventureIdleV100_(
        maintenant
      ){
        if(
          !idleEtat ||
          !idleEtat.aventure
        ){
          return;
        }

        const fin=
          Math.max(
            0,
            idleNombre_(
              idleEtat.aventure.cooldownJusqua
            )
          );

        const restant=
          Math.max(
            0,
            (
              fin-
              maintenant
            )/
            1000
          );

        document
          .querySelectorAll(
            '[id^="sorealIdleAdventureCooldown_"]'
          )
          .forEach(function(el){
            el.textContent=
              restant>0.01
                ?'⏳ Prochaine rencontre dans '+
                  restant.toFixed(1)+
                  ' s'
                :'✅ Rencontre disponible';

            el.classList.toggle(
              'ready',
              restant<=0.01
            );
          });

        const zones=
          idleEtat.aventure&&
          Array.isArray(
            idleEtat.aventure.zones
          )
            ?idleEtat.aventure.zones
            :[];

        document
          .querySelectorAll(
            '.soreal-idle-zone-button-v16[data-aventure-zone]'
          )
          .forEach(function(button){
            const id=
              idleEntier_(
                button.getAttribute(
                  'data-aventure-zone'
                )
              );

            const zone=
              zones.find(function(z){
                return idleEntier_(z.id)===id;
              });


            button.disabled=
              Boolean(
                idleAventureEnCoursV17 ||
                !zone ||
                !zone.debloquee
              );
          });
      }

