      function estBaliseVoixIdleV1_(contenu){
        const tts=window.__SOREAL_IDLE_TUTORIAL_TTS_V209__;
        return Boolean(tts&&typeof tts.resoudreVoixBalise==='function'&&tts.resoudreVoixBalise(contenu));
      }
      function separerNotesHistoireBossIdleV1_(histoire){
        const notes=[];
        let narration=String(histoire||'').trim();
        for(;;){
          const infoMatch=narration.match(/^\(([^\n]+)\)[ \t]*(?:\n|$)\s*/);
          if(!infoMatch||estBaliseVoixIdleV1_(infoMatch[1]))break;
          notes.push('('+String(infoMatch[1]||'').trim()+')');
          narration=narration.slice(infoMatch[0].length).trim();
        }
        return {notes:notes,narration:narration};
      }

      /*
       * Chronique du boss accrochée au mur (Norman, 2026-10-10) : un petit cadre au fond de la salle ; un clic (ou un tap) l'agrandit, un clic dehors, sur la croix ou sur Échap la referme. L'état ouvert survit
       * au redessin de la page (window.__chroniqueOuverteIdleV1). Le panneau reste dans la page en continu : la lecture à voix haute automatique (tutorial-tts) le retrouve toujours.
       */
      /* Main qui montre la chronique : une seule fois sur l'appareil, jamais plus dès le premier clic (même après une Renaissance). */
      function mainChroniqueIdleV1_(){
        try{if(localStorage.getItem('soreal_idle_chronique_main_v1'))return '';}catch(_e){}
        return '<svg class="chro-main-v1" data-sans-traduction aria-hidden="true" viewBox="0 0 40 48"><path d="M14 4c3 0 4 2 4 4v14l2-1c2-1 4 0 4 2l1-1c2-1 4 0 4 2l1-1c2-1 4 0 4 3v10c0 7-5 12-12 12h-4c-5 0-8-3-11-8l-6-9c-1-3 2-5 4-3l3 3V8c0-2 1-4 3-4z" fill="#fff" stroke="#3a2208" stroke-width="2.4" stroke-linejoin="round"/></svg>';
      }
      (function(){
        function panneau(){return document.getElementById('sorealIdleBossChroniqueV206');}
        function poser(ouvert){
          window.__chroniqueOuverteIdleV1=Boolean(ouvert);
          const p=panneau();
          if(p)p.classList.toggle('ouverte',Boolean(ouvert));
        }
        document.addEventListener('click',function(e){
          const cible=e.target;
          const p=cible&&cible.closest?cible.closest('.soreal-idle-boss-lore-v142'):null;
          if(p){
            if(!p.classList.contains('ouverte')){
              if(cible.closest('button,a,[data-soreal-tts-target],[data-texte-admin]'))return;
              try{localStorage.setItem('soreal_idle_chronique_main_v1','1');}catch(_e){}
              const m=p.querySelector('.chro-main-v1');if(m)m.remove();
              poser(true);
            }else if(cible.closest('.soreal-idle-lore-fermer-v1'))poser(false);
            return;
          }
          if(window.__chroniqueOuverteIdleV1)poser(false);
        });
        document.addEventListener('keydown',function(e){
          if(e.key==='Escape'&&window.__chroniqueOuverteIdleV1)poser(false);
          else if((e.key==='Enter'||e.key===' ')&&e.target&&e.target.classList&&e.target.classList.contains('soreal-idle-boss-lore-v142')&&!window.__chroniqueOuverteIdleV1){e.preventDefault();poser(true);}
        });
      })();

      function histoireBossMarkupIdleV142_(
        j
      ){
        const histoire=
          String(
            j&&j.bossHistoire||''
          ).trim();

        /* Historique V8: docs/UI-MONOLITH-HISTORY.md#bloc-147 */
        if(!histoire){
          /* Boss sans chronique : l'administrateur peut quand même lui en écrire une (jamais rien pour un joueur). */
          const Tadmin=window.__SOREAL_IDLE_TEXTES_V1__;
          return Tadmin&&Tadmin.boutonBossHtml&&j&&j.bossId
            ?'<div style="margin:8px 0">'+Tadmin.boutonBossHtml(j.bossId)+'</div>'
            :'';
        }

        const nomBoss=
          String(
            j&&j.bossActuel||'Boss'
          ).trim();

        /* Historique V8: docs/UI-MONOLITH-HISTORY.md#bloc-148 */
        /*
         * 2026-09-24 (Norman) : TOUS les paragraphes du début qui sont entre parenthèses sont des notes sur le jeu (déblocage d'une
         * fonctionnalité, d'une zone...), pas sur le boss : chacun prend la mise en page « note » (avant, seul le premier
         * paragraphe la recevait et les suivants finissaient dans le récit).
         */
        const separe=separerNotesHistoireBossIdleV1_(histoire);
        const notesDeblocage=separe.notes;
        const narration=separe.narration;

        /*
         * data-soreal-chronique-boss-id (Norman, 2026-09-27) : identifiant STABLE du boss dont dépend la lecture automatique une seule fois
         * (modules/tutorial-tts-v202.js, panneauChroniqueBoss_). j.bossId (même valeur que bossCatalogue[].numero) est utilisé plutôt que le
         * nom pour éviter toute ambiguïté ; ce panneau reste rendu en continu tant que l'écran Boss est affiché, contrairement aux popups de
         * tutoriel qui ne sont créés qu'une fois.
         */
        /* Chronique avec balises de voix : le panneau porte le texte à lire (nom + récit brut), sinon la lecture se ferait sur le texte affiché, sans voix. */
        const ttsChronique=window.__SOREAL_IDLE_TUTORIAL_TTS_V209__;
        const attrLecture=(ttsChronique&&typeof ttsChronique.composerChronique==='function'&&attrHistoireVoixIdleV1_(histoire))
          ?' data-soreal-tts-say="'+idleHtml_(ttsChronique.composerChronique(nomBoss,histoire))+'"'
          :'';
        return `
          <div id="sorealIdleBossChroniqueV206" class="soreal-idle-boss-lore-v142${window.__chroniqueOuverteIdleV1?' ouverte':''}" role="button" tabindex="0" aria-label="Chronique du boss" data-soreal-chronique-boss-id="${idleEntier_(j&&j.bossId||0)}"${attrLecture}>
            <button type="button" class="soreal-idle-lore-fermer-v1" aria-label="Fermer" data-soreal-tts-ignore>✕</button>
            ${mainChroniqueIdleV1_()}
            <div class="soreal-idle-boss-lore-title-v168" data-soreal-tts-ignore>Chronique du boss</div>
            <div class="soreal-idle-boss-lore-name-v184" data-soreal-tts-pause="1100">${idleHtml_(nomBoss)}</div>
            <div class="soreal-idle-boss-lore-ornament-v184" data-soreal-tts-ignore>✦ ❦ ✦</div>
            ${notesDeblocage.map(function(note){
              return '<div class="soreal-idle-boss-lore-info-v198" data-soreal-tts-pause="700">'+idleHtml_(note)+'</div>';
            }).join('')}
            ${narration
              ?'<div class="soreal-idle-boss-lore-histoire-v142" data-sans-traduction>'+idleHtml_(sansBaliseVoixIdleV1_(narration))+'</div>'
              :''}
            <button type="button" class="soreal-idle-tts-read-v203" data-soreal-tts-target="sorealIdleBossChroniqueV206">🔊 Lire la chronique</button>
            ${window.__SOREAL_IDLE_TEXTES_V1__?window.__SOREAL_IDLE_TEXTES_V1__.boutonBossHtml(j&&j.bossId):''}
          </div>
        `;
      }


      function capacitesBossMarkupIdleV70_(
        j
      ){
        const caps=
          Array.isArray(
            j&&j.bossCapacites
          )
            ?j.bossCapacites
            :[];

        if(!caps.length){
          return '';
        }

        return `
          <div class="soreal-idle-boss-skills-v70">
            ${caps.map(
              function(c){
                return (
                  '<span class="soreal-idle-boss-skill-chip-v70">'+
                  idleHtml_(
                    labelCapaciteBossIdleV70_(c)
                  )+
                  '</span>'
                );
              }
            ).join('')}
          </div>
        `;
      }


      function preparerCapacitesBossIdleV70_(
        forceReset
      ){
        if(!idleEtat)return;

        const boss=
          String(
            idleEtat.bossActuel||''
          );

        if(
          !forceReset &&
          idleCombatLogBossV70===boss
        ){
          return;
        }

        idleCombatLogBossV70=boss;
        idleBossSpecialNextV70={};
        idleParalysieJusquaV70=0;
        idleBouclierJusquaV70=0;
        idleBouclierReductionV70=0;
        idleFureurActiveV70=false;

        reinitialiserEffetsVisuelsJoueurIdleV112_();

        const now=
          Date.now();

        const caps=
          Array.isArray(
            idleEtat.bossCapacites
          )
            ?idleEtat.bossCapacites
            :[];

        caps.forEach(
          function(cap,index){
            if(
              idleNombre_(
                cap.intervalle
              )>0
            ){
              idleBossSpecialNextV70[
                index
              ]=
                now+
                idleNombre_(
                  cap.intervalle
                )*
                1000;
            }
          }
        );
      }


      function multiplicateurFureurLocaleIdleV70_(){
        if(!idleEtat)return 1;

        const caps=
          Array.isArray(
            idleEtat.bossCapacites
          )
            ?idleEtat.bossCapacites
            :[];

        let mult=1;

        caps.forEach(
          function(cap){
            if(
              String(
                cap.type||''
              ).toLowerCase()==='fureur'
            ){
              mult*=
                1+
                Math.max(
                  0,
                  idleNombre_(
                    cap.valeur
                  )
                )/
                100;
            }
          }
        );

        return mult;
      }


      function traiterCapacitesBossLocalesIdleV70_(
        maintenant
      ){
        if(
          !idleEtat ||
          !idleEtat.combatBossActif
        ){
          return;
        }

        preparerCapacitesBossIdleV70_(
          false
        );

        const caps=
          Array.isArray(
            idleEtat.bossCapacites
          )
            ?idleEtat.bossCapacites
            :[];

        const pvMax=
          Math.max(
            1,
            idleNombre_(
              idleEtat.bossPvMax
            )
          );

        const pct=
          idleNombre_(
            idleEtat.bossPv
          )/
          pvMax*
          100;

        if(
          pct<=30 &&
          !idleFureurActiveV70 &&
          caps.some(
            function(c){
              return String(
                c.type||''
              ).toLowerCase()==='fureur';
            }
          )
        ){
          idleFureurActiveV70=true;

          ajouterLogCombatIdleV70_(
            'skill',
            '🔥 '+
            String(
              idleEtat.bossActuel||'Boss'
            )+
            ' entre en FUREUR !'
          );
        }

        caps.forEach(
          function(cap,index){
            const type=
              String(
                cap.type||''
              ).toLowerCase();

            if(
              type==='fureur' ||
              idleNombre_(
                cap.intervalle
              )<=0
            ){
              return;
            }

            const prochain=
              idleBossSpecialNextV70[index]||
              (
                maintenant+
                idleNombre_(
                  cap.intervalle
                )*
                1000
              );

            if(maintenant<prochain){
              idleBossSpecialNextV70[index]=
                prochain;
              return;
            }

            idleBossSpecialNextV70[index]=
              maintenant+
              idleNombre_(
                cap.intervalle
              )*
              1000;

            if(type==='regen'){
              const soin=
                pvMax*
                Math.max(
                  0,
                  idleNombre_(
                    cap.valeur
                  )
                )/
                100;

              const avant=
                idleNombre_(
                  idleEtat.bossPv
                );

              idleEtat.bossPv=
                Math.min(
                  pvMax,
                  avant+
                  soin
                );

              const reel=
                Math.max(
                  0,
                  idleEtat.bossPv-
                  avant
                );

              if(reel>0){
                ajouterLogCombatIdleV70_(
                  'skill',
                  '💚 '+
                  String(
                    idleEtat.bossActuel||'Boss'
                  )+
                  ' régénère '+
                  formatGrandNombreIdleV70_(
                    reel
                  )+
                  ' ❤️.'
                );
              }
            }

            if(type==='paralysie'){
              idleParalysieJusquaV70=
                Math.max(
                  idleParalysieJusquaV70,
                  maintenant+
                  Math.max(
                    0,
                    idleNombre_(
                      cap.duree
                    )
                  )*
                  1000
                );

              activerEffetVisuelJoueurIdleV112_(
                'paralysie',
                cap.duree,
                idleParalysieJusquaV70
              );

              ajouterLogCombatIdleV70_(
                'skill',
                '⚡ '+
                String(
                  idleEtat.bossActuel||'Boss'
                )+
                ' paralyse '+
                String(
                  idleEtat.nom||'le joueur'
                )+
                ' pendant '+
                idleNombre_(
                  cap.duree
                )+
                ' s.'
              );
            }

            const effetJoueurV112=
              normaliserTypeEffetJoueurIdleV112_(
                type
              );

            if(
              ['gel','feu','poison','stun']
                .indexOf(effetJoueurV112)!==-1
            ){
              activerEffetVisuelJoueurIdleV112_(
                effetJoueurV112,
                Math.max(
                  .1,
                  idleNombre_(cap.duree)||1
                )
              );

              if(effetJoueurV112==='stun'){
                idleParalysieJusquaV70=
                  Math.max(
                    idleParalysieJusquaV70,
                    maintenant+
                    Math.max(
                      .1,
                      idleNombre_(cap.duree)||1
                    )*1000
                  );
              }

              const nomsEffetsV112={
                gel:'❄️ gèle',
                feu:'🔥 brûle',
                poison:'☠️ empoisonne',
                stun:'💫 étourdit'
              };

              ajouterLogCombatIdleV70_(
                'skill',
                String(
                  idleEtat.bossActuel||'Boss'
                )+
                ' '+
                nomsEffetsV112[effetJoueurV112]+
                ' '+
                String(
                  idleEtat.nom||'le joueur'
                )+
                '.'
              );
            }

            if(type==='bouclier'){
              idleBouclierJusquaV70=
                Math.max(
                  idleBouclierJusquaV70,
                  maintenant+
                  Math.max(
                    0,
                    idleNombre_(
                      cap.duree
                    )
                  )*
                  1000
                );

              idleBouclierReductionV70=
                Math.max(
                  idleBouclierReductionV70,
                  Math.max(
                    0,
                    Math.min(
                      95,
                      idleNombre_(
                        cap.valeur
                      )
                    )
                  )
                );

              ajouterLogCombatIdleV70_(
                'skill',
                '🛡️ '+
                String(
                  idleEtat.bossActuel||'Boss'
                )+
                ' active un bouclier : -'+
                idleBouclierReductionV70+
                '% dégâts.'
              );
            }
          }
        );

        if(
          idleBouclierJusquaV70>0 &&
          maintenant>=
          idleBouclierJusquaV70
        ){
          idleBouclierJusquaV70=0;
          idleBouclierReductionV70=0;
        }
      }


      function actualiserXpLocaleIdleV70_(
        gain
      ){
        if(
          !idleEtat ||
          idleNombre_(gain)<=0
        ){
          return;
        }

        let xp=
          Math.max(
            0,
            idleNombre_(
              idleEtat.xp
            )+
            idleNombre_(
              gain
            )
          );

        let niveau=
          Math.max(
            1,
            idleEntier_(
              idleEtat.niveau
            )
          );

        let niveaux=0;

        while(
          xp>=niveau*100 &&
          niveaux<100
        ){
          xp-=niveau*100;
          niveau+=1;
          niveaux+=1;
        }

        idleEtat.xp=xp;
        idleEtat.niveau=niveau;
        idleEtat.xpRequise=
          niveau*100;

        const texte=
          document.getElementById(
            'sorealIdleXpTexteV70'
          );

        const fill=
          document.getElementById(
            'sorealIdleXpFillV70'
          );

        const niveauEl=
          document.getElementById(
            'sorealIdleXpNiveauV70'
          );

        if(texte){
          texte.textContent=
            formatGrandNombreIdleV70_(xp)+
            ' / '+
            formatGrandNombreIdleV70_(
              niveau*100
            )+
            ' XP';
        }

        if(fill){
          fill.style.width=
            Math.max(
              0,
              Math.min(
                100,
                xp/(niveau*100)*100
              )
            )+
            '%';
        }

        if(niveauEl){
          niveauEl.textContent=
            String(niveau);
        }

        if(niveaux>0){
          ajouterLogCombatIdleV70_(
            'reward',
            '⭐ NIVEAU SUPÉRIEUR ! Niveau '+
            niveau+
            '.'
          );

          const panel=
            document.querySelector(
              '.soreal-idle-xp-panel-v70'
            );

          if(panel){
            panel.classList.remove(
              'soreal-idle-levelup-flash-v70'
            );
            void panel.offsetWidth;
            panel.classList.add(
              'soreal-idle-levelup-flash-v70'
            );
          }

          setTimeout(
            function(){
              gererPopupsProgressionIdleV75_(
                idleEtat
              );
              gererTutorielPremierBossIdleV1_(
                idleEtat
              );
            },
            0
          );
        }
      }



      let idleSortActionV90=false;
      let idleSortPurchaseQueueV101=[];
      let idleSortPurchaseBusyV101=false;
      let idleSortPurchaseTimerV101=null;


      function sortParIdIdleV90_(id){
        const sorts=
          idleEtat&&
          idleEtat.magie&&
          Array.isArray(
            idleEtat.magie.sorts
          )
            ?idleEtat.magie.sorts
            :[];

        return sorts.find(
          function(sort){
            return String(
              sort.id||''
            )===String(
              id||''
            );
          }
        )||null;
      }


      function texteEffetSortIdleV90_(
        sort,
        effet
      ){
        const s=sort||{};
        const e=effet||{};

        if(e.type==='soin_boss'){
          return '💚 '+
            String(s.nom||'Sort')+
            ' soigne le boss de '+
            formatGrandNombreIdleV70_(e.valeur)+
            ' ❤️.';
        }

        if(e.type==='degats_sacres'){
          return '✨ '+
            String(s.nom||'Sort')+
            ' brûle le mort-vivant pour '+
            formatGrandNombreIdleV70_(e.valeur)+
            ' dégâts.';
        }

        if(s.type==='heal_pct'){
          return '❤️ '+
            String(s.nom||'Sort')+
            ' rend '+
            formatGrandNombreIdleV70_(e.valeur)+
            ' ❤️.';
        }

        if(
          s.type==='damage_power' ||
          s.type==='damage_boss_pct'
        ){
          return String(s.emoji||'✨')+
            ' '+
            String(s.nom||'Sort')+
            ' inflige '+
            formatGrandNombreIdleV70_(e.valeur)+
            ' dégâts.';
        }

        if(s.type==='shield_pct'){
          return '🛡️ Barrière active : -'+
            idleNombre_(e.valeur)+
            '% dégâts pendant '+
            idleNombre_(e.duree)+
            ' s.';
        }

        if(s.type==='cleanse'){
          return '❄️ Paralysie purgée · immunité '+
            idleNombre_(e.duree)+
            ' s.';
        }

        if(s.type==='vulnerability_pct'){
          return '🌌 Le boss devient vulnérable de +'+
            idleNombre_(e.valeur)+
            '% pendant '+
            idleNombre_(e.duree)+
            ' s.'+
            (
              e.sceauBrise
                ?' Le sceau est brisé.'
                :''
            );
        }

        return String(s.emoji||'✨')+
          ' '+
          String(s.nom||'Sort')+
          ' lancé.';
      }


      function rafraichirMagieOptimisteIdleV101_(){
        conserverPositionIdleV24_(
          function(){
            rendreIdleEtat_({
              ok:true,
              joueur:idleEtat
            });
          }
        );
      }


      function envoyerAchatsSortsIdleV101_(){
        if(
          idleSortPurchaseBusyV101 ||
          !idleSortPurchaseQueueV101.length ||
          !SOREAL_SESSION
        ){
          return;
        }

        const lot=
          idleSortPurchaseQueueV101
            .splice(
              0,
              idleSortPurchaseQueueV101.length
            );

        idleSortPurchaseBusyV101=true;

        google.script.run
          .withSuccessHandler(function(res){
            idleSortPurchaseBusyV101=false;

            if(
              !res ||
              !res.ok
            ){
              /* Historique V8: docs/UI-MONOLITH-HISTORY.md#bloc-149 */
              synchroniserJeuIdleV7_(
                true
              );

              messageFlottantIdleV32_(
                '❌ '+
                (
                  res&&res.message
                    ?res.message
                    :'Achat magique refusé.'
                )
              );
            }else if(
              !idleSortPurchaseQueueV101.length &&
              res.joueur
            ){
              /* Historique V8: docs/UI-MONOLITH-HISTORY.md#bloc-150 */
              idleEtat=
                res.joueur;

              rafraichirMagieOptimisteIdleV101_();
            }

            if(
              idleSortPurchaseQueueV101.length
            ){
              setTimeout(
                envoyerAchatsSortsIdleV101_,
                25
              );
            }
          })
          .withFailureHandler(function(e){
            idleSortPurchaseBusyV101=false;

            synchroniserJeuIdleV7_(
              true
            );

            messageFlottantIdleV32_(
              '❌ '+
              (
                e&&e.message
                  ?e.message
                  :'Erreur pendant l’achat magique.'
              )
            );

            if(
              idleSortPurchaseQueueV101.length
            ){
              setTimeout(
                envoyerAchatsSortsIdleV101_,
                120
              );
            }
          })
          .acheterSortsSorealIdle(
            SOREAL_SESSION,
            lot
          );
      }


      function planifierAchatsSortsIdleV101_(){
        if(idleSortPurchaseTimerV101){
          clearTimeout(
            idleSortPurchaseTimerV101
          );
        }

        idleSortPurchaseTimerV101=
          setTimeout(
            function(){
              idleSortPurchaseTimerV101=null;
              envoyerAchatsSortsIdleV101_();
            },
            55
          );
      }


      function acheterSortIdleV90_(
        sortId
      ){
        if(
          !SOREAL_SESSION ||
          !idleEtat ||
          !idleEtat.magie ||
          !idleEtat.magie.debloquee
        ){
          return;
        }

        const sort=
          sortParIdIdleV90_(
            sortId
          );

        if(
          !sort ||
          sort.achete ||
          !sort.disponibleNiveau
        ){
          return;
        }

        const cout=
          Math.max(
            0,
            idleNombre_(
              sort.coutPieces
            )
          );

        if(
          idleNombre_(
            idleEtat.pieces
          )<
          cout
        ){
          messageFlottantIdleV32_(
            '🪙 Pas assez de pièces.'
          );
          return;
        }

        /* Historique V8: docs/UI-MONOLITH-HISTORY.md#bloc-151 */
        idleEtat.pieces=
          Math.max(
            0,
            idleNombre_(
              idleEtat.pieces
            )-
            cout
          );

        sort.achete=true;
        sort.achetable=false;

        if(
          !Array.isArray(
            idleEtat.magie.sortsAchetes
          )
        ){
          idleEtat.magie.sortsAchetes=[];
        }

        if(
          idleEtat.magie.sortsAchetes.indexOf(
            String(sort.id)
          )===-1
        ){
          idleEtat.magie.sortsAchetes.push(
            String(sort.id)
          );
        }

        if(
          idleSortPurchaseQueueV101.indexOf(
            String(sort.id)
          )===-1
        ){
          idleSortPurchaseQueueV101.push(
            String(sort.id)
          );
        }

        rafraichirMagieOptimisteIdleV101_();

        messageFlottantIdleV32_(
          String(sort.emoji||'🔮')+
          ' Sort appris : '+
          String(sort.nom||'')
        );

        planifierAchatsSortsIdleV101_();
      }


      function lancerSortIdleV90_(
        sortId,
        cible
      ){
        if(
          idleSortActionV90 ||
          !SOREAL_SESSION ||
          !idleEtat
        ){
          return;
        }

        const sort=
          sortParIdIdleV90_(
            sortId
          );

        if(!sort){
          return;
        }

        if(
          String(cible||'')==='boss' &&
          !idleEtat.combatBossActif
        ){
          messageFlottantIdleV32_(
            '⚔️ Lance le combat avant de cibler le boss.'
          );
          return;
        }

        idleSortActionV90=true;

        google.script.run
          .withSuccessHandler(function(res){
            idleSortActionV90=false;

            if(
              !res ||
              !res.ok
            ){
              messageFlottantIdleV32_(
                '❌ '+
                (
                  res&&res.message
                    ?res.message
                    :'Sort impossible.'
                )
              );
              return;
            }

            const nomSort=
              res.sort&&res.sort.nom
                ?res.sort.nom
                :sort.nom;

            ajouterLogCombatIdleV70_(
              'skill',
              texteEffetSortIdleV90_(
                res.sort||sort,
                res.effet||{}
              )
            );

            if(
              res.sort &&
              res.sort.type==='cleanse'
            ){
              idleParalysieJusquaV70=0;
            }

            if(res.joueur){
              /* Historique V8: docs/UI-MONOLITH-HISTORY.md#bloc-152 */
              const adventureRestPvAvantSortV1=idleEtat&&idleEtat.adventureRestPv;
              const joueurSortProtegeV208=
                protegerJoueurServeurInventaireIdleV208_(
                  res.joueur
                );
              if(!appliquerSynchroCombatSansReflowIdleV116_(joueurSortProtegeV208)){
                idleEtat=joueurSortProtegeV208;
                if(adventureRestPvAvantSortV1!=null)idleEtat.adventureRestPv=adventureRestPvAvantSortV1;
              }

              rendreIdleEtat_({
                ok:true,
                joueur:idleEtat
              });
            }

            messageFlottantIdleV32_(
              String(
                res.sort&&res.sort.emoji||'✨'
              )+
              ' '+
              String(nomSort||'Sort')
            );
          })
          .withFailureHandler(function(e){
            idleSortActionV90=false;

            messageFlottantIdleV32_(
              '❌ '+
              (
                e&&e.message
                  ?e.message
                  :'Erreur magique.'
              )
            );
          })
          .lancerSortSorealIdle(
            SOREAL_SESSION,
            String(sortId||''),
            String(cible||'joueur')
          );
      }


      window.__acheterSortIdleV90__=
        acheterSortIdleV90_;

      window.__lancerSortIdleV90__=
        lancerSortIdleV90_;


      function boutonsCibleSortIdleV90_(
        sort,
        compact
      ){
        const cibles=
          Array.isArray(
            sort&&sort.cibles
          )
            ?sort.cibles
            :[];

        const now=heureServeurIdleV1_();

        const cooldown=
          Math.max(
            0,
            (
              idleNombre_(
                sort&&sort.cooldownJusqua
              )-
              now
            )/
            1000
          );

        const mana=
          idleEtat&&idleEtat.magie
            ?idleNombre_(
                idleEtat.magie.mana
              )
            :0;

        const baseDisabled=
          (
            cooldown>0 ||
            mana<
            idleNombre_(
              sort&&sort.coutMana
            ) ||
            idleSortActionV90
          );

        return cibles.map(
          function(cible){
            const boss=
              cible==='boss';

            const disabled=
              baseDisabled ||
              (
                boss &&
                !(
                  idleEtat&&
                  idleEtat.combatBossActif
                )
              );

            if(compact){
              return `
                <button
                  type="button"
                  class="soreal-idle-quick-spell-v90${boss?' boss-target':''}"
                  data-sort-idle-v90="${idleHtml_(sort.id)}"
                  data-sort-target-v90="${idleHtml_(cible)}"
                  onclick="window.__lancerSortIdleV90__('${idleHtml_(sort.id)}','${idleHtml_(cible)}')"
                  ${disabled?'disabled':''}
                >
                  ${idleHtml_(sort.emoji||'✨')}
                  ${boss?'Boss':'Moi'}
                  <small>
                    ${formatGrandNombreIdleV70_(sort.coutMana)} mana
                    ${
                      cooldown>0
                        ?' · '+cooldown.toFixed(0)+'s'
                        :''
                    }
                  </small>
                </button>
              `;
            }

            return `
              <button
                type="button"
                class="soreal-idle-spell-button-v90${boss?' boss-target':''}"
                data-sort-idle-v90="${idleHtml_(sort.id)}"
                data-sort-target-v90="${idleHtml_(cible)}"
                onclick="window.__lancerSortIdleV90__('${idleHtml_(sort.id)}','${idleHtml_(cible)}')"
                ${disabled?'disabled':''}
              >
                ${boss?'👹 Cibler le boss':'❤️ Me cibler'}
                ${
                  cooldown>0
                    ?' · '+cooldown.toFixed(0)+'s'
                    :''
                }
              </button>
            `;
          }
        ).join('');
      }


