      function actualiserManaSortsIdleV90_(
        maintenant
      ){
        const magie=
          idleEtat&&idleEtat.magie
            ?idleEtat.magie
            :null;

        if(
          !magie ||
          !magie.debloquee
        ){
          return;
        }

        const max=
          Math.max(
            1,
            idleNombre_(
              magie.manaMax
            )
          );

        magie.mana=
          Math.min(
            max,
            Math.max(
              0,
              idleNombre_(
                magie.mana
              )+
              Math.max(
                0,
                idleNombre_(
                  magie.regenSeconde
                )
              )*
              (
                Math.max(
                  0,
                  maintenant-
                  (
                    magie.__tickLocalV90||
                    maintenant
                  )
                )/
                1000
              )
            )
          );

        magie.__tickLocalV90=
          maintenant;

        const texte=
          document.getElementById(
            'sorealIdleManaTextV90'
          );

        if(texte){
          texte.textContent=
            formatGrandNombreIdleV70_(
              magie.mana
            )+
            ' / '+
            formatGrandNombreIdleV70_(
              max
            );
        }

        const fill=
          document.getElementById(
            'sorealIdleManaFillV90'
          );

        if(fill){
          fill.style.width=
            Math.max(
              0,
              Math.min(
                100,
                magie.mana/max*100
              )
            )+
            '%';
        }

        document
          .querySelectorAll(
            '[data-sort-idle-v90]'
          )
          .forEach(function(button){
            const sort=
              sortParIdIdleV90_(
                button.getAttribute(
                  'data-sort-idle-v90'
                )
              );

            if(!sort)return;

            const cible=
              button.getAttribute(
                'data-sort-target-v90'
              )||'joueur';

            const restant=
              Math.max(
                0,
                (
                  idleNombre_(
                    sort.cooldownJusqua
                  )-
                  heureServeurIdleV1_()
                )/
                1000
              );

            button.disabled=
              Boolean(
                idleSortActionV90 ||
                restant>0 ||
                idleNombre_(
                  magie.mana
                )<
                idleNombre_(
                  sort.coutMana
                ) ||
                (
                  cible==='boss' &&
                  !idleEtat.combatBossActif
                )
              );

            const small=
              button.querySelector(
                'small'
              );

            if(small){
              small.textContent=
                formatGrandNombreIdleV70_(
                  sort.coutMana
                )+
                ' mana'+
                (
                  restant>0
                    ?' · '+
                      restant.toFixed(0)+
                      's'
                    :''
                );
            }
          });
      }


